PRAGMA foreign_keys=ON;
CREATE TABLE categories(id TEXT PRIMARY KEY,name TEXT NOT NULL,parent_id TEXT REFERENCES categories(id),position INTEGER DEFAULT 0,active INTEGER DEFAULT 1);
CREATE TABLE products(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT DEFAULT '',category_id TEXT REFERENCES categories(id),image TEXT DEFAULT '',active INTEGER DEFAULT 1,featured INTEGER DEFAULT 0,ingredients TEXT DEFAULT '',allergens TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE product_variants(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),name TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>=0),old_price INTEGER CHECK(old_price>=0),stock INTEGER CHECK(stock>=0),available INTEGER DEFAULT 1,position INTEGER DEFAULT 0);
CREATE INDEX variants_product ON product_variants(product_id);
CREATE INDEX products_category ON products(category_id,active);
CREATE TABLE store_settings(id INTEGER PRIMARY KEY CHECK(id=1),data TEXT NOT NULL);
INSERT INTO store_settings VALUES(1,'{"name":"حلويات شجرة آدم","whatsapp":"","address":"","hours":"","open":false}');
CREATE TABLE delivery_zones(id TEXT PRIMARY KEY,name TEXT NOT NULL,fee INTEGER NOT NULL CHECK(fee>=0),active INTEGER DEFAULT 1);
CREATE TABLE admin_users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,salt TEXT NOT NULL);
CREATE TABLE admin_sessions(id TEXT PRIMARY KEY,user_id TEXT REFERENCES admin_users(id),expires INTEGER NOT NULL);
CREATE TABLE rate_limits(id TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE orders(id INTEGER PRIMARY KEY AUTOINCREMENT,idempotency TEXT UNIQUE NOT NULL,payload_hash TEXT NOT NULL,customer TEXT NOT NULL,items TEXT NOT NULL,total INTEGER NOT NULL,delivery INTEGER NOT NULL,status TEXT DEFAULT 'بانتظار الإرسال',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
